            return None
        return self.channel_packs.resolve(pack_id).source_path

    def _channel_pack_required(self, workspace_id: str, *, remote_channel_id: str | None = None) -> dict[str, Any]:
        self.store.set_workspace_health(workspace_id, "BLOCKED")
        return {
            "result": {
                "status": "CHANNEL_PACK_REQUIRED",
                "operation_id": None,
                "workspace_id": workspace_id,
                "remote_channel_id": remote_channel_id,
                "next_action": "select the desired Channel Pack, then continue onboarding",
            },
            "workspace": self.workspace_overview(workspace_id),
        }

    def _continue_after_channel_binding(
        self,
        workspace_id: str,
        remote_channel_id: str | None,
    ) -> dict[str, Any]:
        if self._selected_channel_pack_path(workspace_id) is None:
            return self._channel_pack_required(
                workspace_id,
                remote_channel_id=remote_channel_id,
            )
        return self._continue_channel_configuration(workspace_id)

    def _continue_channel_creation(self, workspace_id: str) -> dict[str, Any]:
        pack_path = self._selected_channel_pack_path(workspace_id)
        if pack_path is None:
            return self._channel_pack_required(workspace_id)
        runner = self._runner_for_workspace(
            workspace_id,
            script="channel_create_runtime.mjs",
        )
        result = ChannelCreationService(
            self.store,
            self.youtube,
            RawCDPChannelCreationAdapter(runner),
        ).ensure_created(
            workspace_id,
            cdp_url=self._cdp_url_for_workspace(workspace_id),
            pack_path=pack_path,
        )
        if result.status in {"BOUND_CREATED_CHANNEL", "BOUND_EXACT_CHANNEL"}:
            return self._continue_after_channel_binding(workspace_id, result.remote_channel_id)
        return {"result": asdict(result), "workspace": self.workspace_overview(workspace_id)}

    def _continue_channel_configuration(self, workspace_id: str) -> dict[str, Any]:
        pack_path = self._selected_channel_pack_path(workspace_id)
        if pack_path is None:
            workspace = self.store.get_workspace(workspace_id)
            remote_channel_id = None
            if workspace.get("youtube_channel_id"):
                remote_channel_id = str(
                    self.store.get_youtube_channel(str(workspace["youtube_channel_id"]))["remote_channel_id"]
                )
            return self._channel_pack_required(
                workspace_id,
                remote_channel_id=remote_channel_id,
            )
        result = self.apply_channel_pack(workspace_id, str(pack_path))
        status = str(result.get("result", {}).get("status") or "")
        if status == "SUCCEEDED":
            self.store.set_workspace_health(workspace_id, "READY")
            return self.inspect_eligibility(workspace_id)
        elif status == "RECONCILE_REQUIRED":
            self.store.set_workspace_health(workspace_id, "DEGRADED")
            result["workspace"] = self.workspace_overview(workspace_id)
        return result

    def apply_selected_channel_pack(self, workspace_id: str) -> dict[str, Any]:
        pack_path = self._selected_channel_pack_path(workspace_id)
        if pack_path is None:
            raise ControlCenterError("select a Channel Pack before applying channel configuration")
        return self.apply_channel_pack(workspace_id, str(pack_path))

    def recover_approved_channel_description(
        self,
        workspace_id: str,
        predecessor_effect_id: str,
        approved_description_digest: str,
    ) -> dict[str, Any]:
        pack_path = self._selected_channel_pack_path(workspace_id)
        if pack_path is None:
            raise ControlCenterError("selected Channel Pack is required for description recovery")
        runner = self._runner_for_workspace(workspace_id)
        result = ChannelPackService(
            self.store, RawCDPChannelPackAdapter(runner)
        ).recover_approved_description(
            workspace_id,
            pack_path,
            predecessor_effect_id=predecessor_effect_id,
            approved_description_digest=approved_description_digest,
        )
        if result.status == "SUCCEEDED":
            self.store.set_workspace_health(workspace_id, "READY")
            return self.inspect_eligibility(workspace_id)
        return {"result": asdict(result), "workspace": self.workspace_overview(workspace_id)}

    def recover_approved_channel_avatar(
        self,
        workspace_id: str,
        predecessor_effect_id: str,
        approved_avatar_digest: str,
    ) -> dict[str, Any]:
        pack_path = self._selected_channel_pack_path(workspace_id)
        if pack_path is None:
            raise ControlCenterError("selected Channel Pack is required for avatar recovery")
        runner = self._runner_for_workspace(workspace_id)
        result = ChannelPackService(
            self.store, RawCDPChannelPackAdapter(runner)
        ).recover_approved_avatar(
            workspace_id,
            pack_path,
            predecessor_effect_id=predecessor_effect_id,
            approved_avatar_digest=approved_avatar_digest,
        )
        if result.status == "SUCCEEDED":
            self.store.set_workspace_health(workspace_id, "READY")
            return self.inspect_eligibility(workspace_id)
        return {"result": asdict(result), "workspace": self.workspace_overview(workspace_id)}

