(async()=>{
await vm.runInContext(`(async()=>{
 workspaces=[{workspace_id:'A',browser:{runtime_state:'RUNNING_ATTACHABLE'}},{workspace_id:'B',browser:{runtime_state:'RUNNING_ATTACHABLE'}}];selected='A';
 let resolveRequest,requests=0;api=()=>{requests++;return new Promise(resolve=>resolveRequest=resolve)};
