 let resolveSelection;api=()=>new Promise(resolve=>resolveSelection=resolve);let modalCount=0;openChannelSelection=()=>modalCount++;
 const selection=inspectChannel();selectWorkspace('B');resolveSelection({result:{status:'CHANNEL_SELECTION_REQUIRED',candidate_channel_ids:['UC_A','UC_B'],next_action:'Choose a channel'}});await selection;
 if(modalCount!==0)throw Error('foreign Workspace modal opened');
